cat > /tmp/sms-check.mjs <<'EOF'
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-dev2-haiku/work/ours-g1-2/bot.mjs';
const ok = { marketingConsent: true, optedOutAt: null, timeZone: 'America/Chicago' };
const mk = (to, kind = 'marketing') => ({ kind, body: 'x', to: { phone: '+13125550142', ...to } });
// 2026-10-23 is CDT (UTC-5). Chicago 10:00 = 15:00Z.
const cases = [
  ['allowed midday', mk(ok), '2026-10-23T15:00:00Z', { allowed: true, reason: null }],
  ['window start 08:00 included', mk(ok), '2026-10-23T13:00:00Z', { allowed: true, reason: null }],
  ['21:00 excluded', mk(ok), '2026-10-24T02:00:00Z', { allowed: false, reason: 'outside_marketing_hours' }],
  ['20:59 allowed', mk(ok), '2026-10-24T01:59:00Z', { allowed: true, reason: null }],
  ['07:59 blocked', mk(ok), '2026-10-23T12:59:00Z', { allowed: false, reason: 'outside_marketing_hours' }],
  ['no consent false', mk({ ...ok, marketingConsent: false }), '2026-10-23T15:00:00Z', { allowed: false, reason: 'marketing_no_consent' }],
  ['no consent absent', mk({ ...ok, marketingConsent: undefined }), '2026-10-23T15:00:00Z', { allowed: false, reason: 'marketing_no_consent' }],
  ['opted out', mk({ ...ok, optedOutAt: '2026-10-01T12:00:00Z' }), '2026-10-23T15:00:00Z', { allowed: false, reason: 'opted_out' }],
  ['opt-out field missing', mk({ ...ok, optedOutAt: undefined }), '2026-10-23T15:00:00Z', { allowed: false, reason: 'opt_out_status_unknown' }],
  ['bad zone', mk({ ...ok, timeZone: 'Mars/Olympus' }), '2026-10-23T15:00:00Z', { allowed: false, reason: 'invalid_timezone' }],
  ['missing zone', mk({ ...ok, timeZone: undefined }), '2026-10-23T15:00:00Z', { allowed: false, reason: 'invalid_timezone' }],
  ['transactional ignores consent+opt-out', mk({ ...ok, marketingConsent: false, optedOutAt: '2026-10-01T12:00:00Z' }, 'transactional'), '2026-10-23T03:00:00Z', { allowed: true, reason: null }],
  ['unknown kind', { kind: 'promo', body: 'x', to: ok }, '2026-10-23T15:00:00Z', { allowed: false, reason: 'unknown_message_kind' }],
];
let fail = 0;
for (const [name, msg, now, want] of cases) {
  const got = checkSms(msg, new Date(now));
  const pass = JSON.stringify(got) === JSON.stringify(want);
  if (!pass) fail++;
  console.log(pass ? 'PASS' : 'FAIL', name, JSON.stringify(got));
}
try { checkSms(mk(ok), 'nope'); console.log('FAIL bad now did not throw'); fail++; } catch (e) { console.log('PASS bad now throws:', e.message); }
console.log(fail === 0 ? 'ALL PASS' : `${fail} FAILED`);
process.exitCode = fail ? 1 : 0;
EOF
for tz in UTC Asia/Tokyo America/Los_Angeles; do echo "== server TZ=$tz"; TZ=$tz node /tmp/sms-check.mjs || echo EXIT $?; done; rm -f /tmp/sms-check.mjs

